        for c in range(cols):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find pattern by extracting from rows that have non-bg values in clusters
    # Look for first row after bg-sparse area with pattern values
    pattern = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                pattern.append(grid[r][c])

    # Pattern should be unique values in order of appearance
    seen = set()
    unique_pattern = []
    for p in pattern:
        if p not in seen:
            seen.add(p)
            unique_pattern.append(p)

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == bg:
                output[r][c] = bg
            else:
                # Replace all non-bg non-misc values using the unique pattern
                output[r][c] = unique_pattern[(unique_pattern.index(val) + c) % len(unique_pattern)]

    return output
